// SPDX-License-Identifier: MIT
// ARM7 (secondary CPU) entry point. All game logic lives on the ARM9; the ARM7
// only drives the touch screen, SPI and sound hardware.
#include <nds.h>

int main(void) {
	irqInit();
	irqSet(IRQ_VCOUNT, VcountCallback);
	irqEnable(IRQ_VCOUNT);

	fifoInit();
	soundInit();

	while (1) {
		swiWaitForVBlank();
		scanKeys();

		touchPosition touch;
		touchRead(&touch);
		IPC_TouchState state = {
			touch.px, touch.py,
			(keysHeld() & KEY_TOUCH) ? 1 : 0,
			keysDown() & KEY_TOUCH ? 1 : 0,
			(keysUp() & KEY_TOUCH) ? 1 : 0,
		};
		IPC_SendTouchState(&state);
	}
	return 0;
}

