// SPDX-License-Identifier: MIT
// Texture set - mirrors the fields of core/src/main/java/com/elementia/core/Assets.java
#pragma once

#include "gfx.h"
#include "element.h"

typedef struct {
	Tex grass, dirt, stone, ice, snow, brick, lavaA, lavaB, water;
	Tex platform;   // 32x14 one-way slab
	Tex crystal;    // 24x30 solid decor
	Tex tree;       // 32x48 background decoration
	Tex chest;      // 28x24
	Tex hero;       // 56x76
	Tex slime[4];   // 44x38 squash cycle
	Tex wisp;       // 16x14
	Tex golem;      // 56x52
	Tex boss;       // 88x76
	Tex slash;      // 96x96 crescent
	Tex waypoint;   // 40x56
	Tex icon[EL_COUNT]; // 24x24
	Tex glow;       // 32x32 radial falloff
} Assets;

extern Assets art;

void assetsInit(void);

/** Tile texture for a tile id, mirroring Assets#texForTile. */
const Tex *assetsTexForTile(int tileId);
/** Background parallax silhouette colour per zone, 0xRRGGBB. */
u32 assetsZoneColor(int zone, int layer);

// SPDX-License-Identifier: MIT
// Procedural audio - a port of core/src/main/java/com/elementia/core/Sfx.java
#pragma once

#include <nds.h>

typedef enum {
	SFX_JUMP,
	SFX_DOUBLE_JUMP,
	SFX_DASH,
	SFX_SLASH,
	SFX_HIT,
	SFX_ENEMY_DIE,
	SFX_HURT,
	SFX_SKILL,
	SFX_BURST,
	SFX_WAYPOINT,
	SFX_TALK,
	SFX_BURN,
	SFX_MELT,
	SFX_ROAR,
	SFX_VICTORY,
	SFX_SPLASH,
	SFX_COUNT
} SfxId;

void sfxInit(void);
void sfxPlay(SfxId id, float volume, float pitch);
void sfxPlaySimple(SfxId id);
void musicStart(void);
void musicStop(void);
void musicSetVolume(float v);
void sfxSetVolume(float v);

// SPDX-License-Identifier: MIT
// Input - port of InputState.java plus the DS button/touch sampling.
#pragma once

#include <nds.h>

typedef struct {
	bool left, right, up, down, jumpHeld;
	bool jumpPressed, attackPressed, skillPressed, dashPressed;
} InputState;

void inputInit(void);
/** Samples the DS pad, ORs the result into `st` (used by touch controls). */
void inputPoll(InputState *st);
/** Clears the edge triggered fields, like InputState#reset. */
void inputResetEdges(InputState *st);

/** Raw accessors for the touch control layer. */
bool inputTouchDown(void);
bool inputTouchPressed(void);
bool inputTouchReleased(void);
u16 inputTouchX(void);
u16 inputTouchY(void);
u16 inputKeysHeld(void);
u16 inputKeysDown(void);

// SPDX-License-Identifier: MIT
// Entities - ports of world/Entity.java, Player.java, Enemy.java, Boss.java,
// Projectile.java and Particles.java.
#pragma once

#include "config.h"
#include "element.h"

#define MAX_ENEMIES  32
#define MAX_PROJ     64
#define PARTICLE_N  160

typedef struct Entity {
	float x, y, w, h;
	float vx, vy;
	bool grounded;
	int facing;
	float hp, maxHp;
	bool alive;
	float hitFlash;
	float statusLife;
	Element status;
	float deadTimer;
} Entity;

typedef enum {
	PS_IDLE, PS_RUN, PS_JUMP, PS_FALL, PS_DASH, PS_ATTACK, PS_HURT, PS_DEAD
} PlayerState;

typedef struct {
	Entity e;
	u32 abilities;
	Element activeElement;   // -1 when no element unlocked yet
	float skillCd, burstGauge, burstPower;
	bool burstReady;
	int comboStep;
	float comboWindow, attackTimer;
	float atkCx, atkCy, atkRadius;
	bool atkHitApplied;
	float coyote, jumpBuffer;
	float dashTimer, dashCd;
	int jumpsUsed;
	float invuln;
	PlayerState state;
} Player;

typedef enum { EK_SLIME, EK_WISP, EK_GOLEM } EnemyKind;

typedef struct {
	Entity e;
	EnemyKind kind;
	Element element;
	float timer, hopTimer;
	float sx0, sx1;
	float homeX, homeY;
	float anim;
	bool angered;
	int contactDmg;
} Enemy;

typedef struct {
	Entity e;
	int phaseTimer, attackIdx;
	int intro;
	bool enraged, teleport, defeated, wobble;
	float volleyTimer;
} Boss;

typedef struct {
	float x, y, vx, vy, w, h, radius;
	float damage;
	Element element;
	bool fromEnemy;
	float life;
	bool alive;
} Projectile;

typedef struct {
	float x[PARTICLE_N], y[PARTICLE_N], vx[PARTICLE_N], vy[PARTICLE_N];
	float life[PARTICLE_N], maxLife[PARTICLE_N], size[PARTICLE_N];
	u32 color[PARTICLE_N];
	bool grav[PARTICLE_N];
	int head;
} Particles;

/* -- entity helpers -------------------------------------------------------- */
void entityTick(Entity *e, float dt);
void entityApplyDamage(Entity *e, float dmg, bool crit, float knockX, float knockY);
bool entityRectOverlap(const Entity *a, float x, float y, float w, float h);

void playerInit(Player *p, float x, float y);
void playerTickTimers(Player *p, float dt);
void playerUpdateState(Player *p);
bool playerHas(const Player *p, u32 ability);
bool playerCanDoubleJump(const Player *p);
void playerUnlock(Player *p, u32 ability);

void enemyInit(Enemy *e, EnemyKind kind, Element element, float x, float y);
void enemyTickTimers(Enemy *e, float dt);

void particlesInit(Particles *ps);
void particlesEmit(Particles *ps, float px, float py, float vx, float vy,
                   u32 color, float size, float life, bool grav);
void particlesBurst(Particles *ps, float px, float py, u32 color, int count,
                    float speed, float size, float life);
void particlesSparks(Particles *ps, float px, float py, u32 color);
void particlesUpdate(Particles *ps, float dt, float groundY);
void particlesClear(Particles *ps);

