// World - port of core/src/main/java/com/elementia/world/World.java
#pragma once

#include "entities.h"
#include "input.h"

#define MW 150
#define MH 46

typedef enum { T_AIR = 0, T_GRASS, T_DIRT, T_STONE, T_ICE, T_SNOW,
