typedef enum { GATE_VINE, GATE_FROST, GATE_MAGMA, GATE_FIRE, GATE_COUNT } GateType;

typedef struct { float x, y, w, h; GateType type; bool active; } Gate;
typedef struct { float x, y; int type; bool opened; } Chest;
typedef struct { float x, y; bool active; } Waypoint;
