static u32 utf8Next(const char **sp) {
    const u8 *s = (const u8 *)*sp;
    u32 c = *s++;
    if (c < 0x80) { *sp = (const char *)s; return c; }
    if (c < 0xc0) { *sp = (const char *)s; return 0xFFFD; }  /* stray continuation */
