```c
static u32 utf8Next(const char **sp) {
    const u8 *s = (const u8 *)*sp;
    u32 c = *s;
    u32 n, i;
    u32 v;
    if (c == 0) { return 0; }            /* *sp unchanged, still at NUL */
    if (c < 0x80) { *sp = (const char *)(s + 1); return c; }
    if (c < 0xc2) { *sp = (const char *)(s + 1); return 0xFFFD; }   /* continuation or overlong lead */
    n = (c < 0xe0) ? 1 : (c < 0xf0) ? 2 : 3;
    v = c & (u32)(0x3f >> n);
    for (i = 1; i <= n; i++) {
        if ((s[i] & 0xc0) != 0x80) { *sp = (const char *)(s + i); return 0xFFFD; }  /* hmm, also stop at NUL */
        v = (v << 6) | (s[i] & 0x3f);
    }
    *sp = (const char *)(s + n + 1);
    return v;
}
