static const FontGlyph *findGlyph(const BFont *f, u32 cp) {
    u32 slot = cp & 0x1ff;
    if (f->cacheIdx[slot] && f->cacheCp[slot] == cp) return &f->glyphs[f->cacheIdx[slot] - 1];
    /* binary search */
    u32 lo = 0, hi = f->count;
    while (lo < hi) { u32 mid = (lo + hi) >> 1; if (f->glyphs[mid].codepoint < cp) lo = mid + 1; else hi = mid; }
    if (lo < f->count && f->glyphs[lo].codepoint == cp) {
        f->cacheCp[slot] = cp; f->cacheIdx[slot] = (u16)(lo + 1);
        return &f->glyphs[lo];
    }
    f->cacheCp[slot] = cp; f->cacheIdx[slot] = 0;
    return NULL;
}
