```c
static void texBlit(const Tex *t, int sx, int sy, int sw, int sh,
                    int dx, int dy, int dw, int dh, bool flipX)
{
	const u16 *texel;
	const u32 *maskRowBase;
	s32 stepX, stepY, fx, fy;
	int skipX, skipY, x, y, mw;
	bool masked, plain;
	u32 alpha, invAlpha;

	if (t == NULL || t->px == NULL || sw <= 0 || sh <= 0 || dw <= 0 || dh <= 0) return;
	if (sx >= (int)t->w || sy >= (int)t->h) return;
	if (sx + sw > (int)t->w) sw = (int)t->w - sx;
	if (sy + sh > (int)t->h) sh = (int)t->h - sy;
	if (sw <= 0 || sh <= 0) return;

	stepX = ((s32)sw << 16) / dw;
	stepY = ((s32)sh << 16) / dh;

	skipX = 0;
	skipY = 0;
	if (dx < 0) { skipX = -dx; dx = 0; dw -= skipX; }
	if (dy < 0) { skipY = -dy; dy = 0; dh -= skipY; }
	if (dw <= 0 || dh <= 0 || dx >= SCRW || dy >= SCRH) return;
	if (dx + dw > SCRW) dw = SCRW - dx;
	if (dy + dh > SCRH) dh = SCRH - dy;
	if (dw <= 0 || dh <= 0) return;

	fx = ((s32)sx << 16) + (s32)skipX * stepX;
	if (flipX) {
		fx += (s32)(sw - 1) << 16;
		stepX = -stepX;
	}
	fy = ((s32)sy << 16) + (s32)skipY * stepY;

	masked = (t->mask != NULL);
	mw = ((int)t->w + 31) >> 5;
	alpha = gTintA;
	invAlpha = 255u - alpha;
	plain = tintIsWhite;

	for (y = 0; y < dh; y++) {
