    Texture texForTile(int t) {
        switch (t) {
            case GRASS: return Assets.t_grass;
            case DIRT: return Assets.t_dirt;
            case STONE: return Assets.t_stone;
            case ICE_T: return Assets.t_ice;
            case SNOW: return Assets.t_snow;
            case BRICK: return Assets.t_brick;
            case CRYST: return Assets.t_crystal;
            case LAVA_T: return (int) (time * 4 + t) % 2 == 0 ? Assets.t_lavaA : Assets.t_lavaB;
            default: return Assets.whiteDot;
        }
    }

    /** Column-based zone (used for ambient, waypoints etc.). */
    int zoneAt(float wx) {
        int c = (int) (wx / T);
        if (c < 40) return 0;
        if (c < 71) return 1;
        if (c < 98) return 2;
        return 3;
    }

    /** View zone: drops to the volcanic underworld when the camera dives deep. */
    int viewZone(float camX, float camY) {
        int z = zoneAt(camX + Config.VIEW_W / 2);
        if (z >= 3 && camY < 200) return 4;
        return z;
    }

    /** Tile zone: below the sanctum/forge floor the whole region becomes the volcano. */
    int tileZone(int col, int row) {
        int z = zoneAt(col * T);
        if (col >= 98 && row >= 34) return 4;
        return z;
    }

    Color zoneColor(int zone, float alpha) {
        switch (zone) {
            case 0: return new Color(1f, 1f, 0.97f, alpha);
            case 1: return new Color(0.58f, 0.62f, 0.82f, alpha);
            case 2: return new Color(0.82f, 0.93f, 1f, alpha);
            case 3: return new Color(1f, 0.74f, 0.82f, alpha);
            case 4: return new Color(0.62f, 0.42f, 0.36f, alpha);
            default: return new Color(1, 1, 1, alpha);
        }
    }

    Color zoneTint(int zone) {
        switch (zone) {
            case 0: return new Color(0.32f, 0.53f, 0.82f, 1);
            case 1: return new Color(0.12f, 0.12f, 0.2f, 1);
            case 2: return new Color(0.48f, 0.62f, 0.78f, 1);
            case 3: return new Color(0.22f, 0.12f, 0.28f, 1);
            case 4: return new Color(0.15f, 0.04f, 0.03f, 1);
            default: return new Color(0.3f, 0.5f, 0.8f, 1);
        }
    }

    // ---------- save/load (via Gdx Preferences) ----------

    public boolean saveDirty;

    public String save() {
        StringBuilder sb = new StringBuilder();
        sb.append("{x:").append(player.x);
        sb.append(";y:").append(player.y);
        sb.append(";hp:").append(player.hp);
        sb.append(";mx:").append(player.maxHp);
        sb.append(";ab:");
        for (Ability a : player.abilities) {
            if (sb.charAt(sb.length() - 1) != ':') sb.append(',');
            sb.append(a.name());
        }
        sb.append(";vine:").append(vineBurned);
        sb.append(";frost:").append(frostMelted);
        sb.append(";fire:").append(fireDoused);
        sb.append(";bd:").append(bossDefeated);
        sb.append(";tr:").append(trophyClaimed);
        sb.append(";won:").append(gameWon);
        sb.append(";rx:").append(respawnX);
        sb.append(";ry:").append(respawnY);
        sb.append(";ch:");
        for (Chest c : chests) sb.append(c.opened ? "1" : "0");
        sb.append("}");
        return sb.toString();
    }

    /** Restore a previously saved state; silently ignores a corrupt save. */
    public void load(String data) {
        if (data == null || data.isEmpty()) return;
        try {
            Map<String, String> kv = new HashMap<>();
            String inner = data.replace("{", "").replace("}", "");
            for (String pair : inner.split(";")) {
                int i = pair.indexOf(':');
                if (i <= 0) continue;
                kv.put(pair.substring(0, i), pair.substring(i + 1));
            }
            player.setPos(parseF(kv, "x", player.x), parseF(kv, "y", player.y));
            player.maxHp = (int) Math.min(200, parseF(kv, "mx", player.maxHp));
            player.hp = (int) Math.min(player.maxHp, parseF(kv, "hp", player.hp));
            player.abilities = Ability.starting();
            String ab = kv.getOrDefault("ab", "");
            if (!ab.isEmpty()) for (String a : ab.split(",")) {
                try { player.abilities.add(Ability.valueOf(a.trim())); } catch (Exception ignored) {}
            }
            vineBurned = parseB(kv, "vine");
            frostMelted = parseB(kv, "frost");
            fireDoused = parseB(kv, "fire");
            bossDefeated = parseB(kv, "bd");
            trophyClaimed = parseB(kv, "tr");
            gameWon = parseB(kv, "won");
            // parse and validate respawn (rx, ry) - player position (x,y) can be mid-air
            respawnX = parseF(kv, "rx", respawnX);
            respawnY = parseF(kv, "ry", respawnY);
            if (respawnY < 0 || tileAt(respawnX, respawnY - 2) == AIR) {
                respawnX = 12 * T;
                respawnY = (MH - 1 - 28) * T;
            }
            player.setPos(parseF(kv, "x", player.x), parseF(kv, "y", player.y));
            player.maxHp = (int) Math.min(200, parseF(kv, "mx", player.maxHp));
            player.hp = (int) Math.min(player.maxHp, parseF(kv, "hp", player.hp));
            String chs = kv.getOrDefault("ch", "");
            for (int i = 0; i < chests.size() && i < chs.length(); i++)
                chests.get(i).opened = chs.charAt(i) == '1';
            for (Gate g : gates) {
                if (g.type == GateType.VINE && vineBurned) g.active = false;
                if (g.type == GateType.FROST && frostMelted) g.active = false;
                if (g.type == GateType.MAGMA && bossDefeated) g.active = false;
                if (g.type == GateType.FIRE && fireDoused) g.active = false;
            }
            if (bossDefeated) {
                player.unlock(Ability.DOUBLE_JUMP);
                player.unlock(Ability.BURST);
            }
            player.setElement(Element.ANEMO);
            player.updateRect();
            saveDirty = false;
            introPending = false;
        } catch (Exception e) {
            System.err.println("Elementia: failed to load save (" + e + "); starting fresh");
            saveDirty = true; // rewrite a fresh save next frame
        }
    }

    private static float parseF(Map<String, String> kv, String key, float def) {
        String s = kv.get(key);
        if (s == null || s.isEmpty()) return def;
        try { return Float.parseFloat(s); } catch (Exception e) { return def; }
    }

    private static boolean parseB(Map<String, String> kv, String key) {
        String s = kv.get(key);
        return s != null && s.equals("true");
    }

    // ---------- math helpers ----------

    static float dist(float x1, float y1, float x2, float y2) {
        return (float) Math.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
    }

    static boolean rectsOverlap(float x1, float y1, float w1, float h1, float x2, float y2, float w2, float h2) {
        return x1 < x2 + w2 && x1 + w1 > x2 && y1 < y2 + h2 && y1 + h1 > y2;
    }

    public float getShakeX() { return shakeTimer > 0 ? (float) Math.random() * shakeAmt * 2 - shakeAmt : 0; }
    public float getShakeY() { return shakeTimer > 0 ? (float) Math.random() * shakeAmt * 2 - shakeAmt : 0; }
}

