        Art.fillRect(p, cx - 16, base, 12, 14, colD);
        Art.fillRect(p, cx + 4, base, 12, 14, colD);
        // body
        drawPoly(p, cx - 20, base + 14, cx + 20, base + 14, cx + 16, base + 38, cx - 16, base + 38, 0xffcc9c3c);
        drawPoly(p, cx - 17, base + 16, cx + 17, base + 16, cx + 14, base + 36, cx - 14, base + 36, col);
        // head
        Art.fillRect(p, cx - 14, base + 38, 28, 12, 0xff2b2b35);
        Art.fillRect(p, cx - 12, base + 40, 24, 10, col);
        Art.fillRect(p, cx - 9, base + 42, 7, 5, 0xff5b3a12);
        Art.fillRect(p, cx + 2, base + 42, 7, 5, 0xff5b3a12);
        // arms
        Art.fillRect(p, cx - 24, base + 22, 8, 14, colD);
        Art.fillRect(p, cx + 16, base + 22, 8, 14, colD);
