        Art.glow(p, cx, base + 28, 10, 0xaa);
        Art.fillEllipse(p, cx, base + 28, 5, 6, 0xffffffff);
        Art.fillEllipse(p, cx, base + 28, 4, 5, 0xc8ffee58);
