    // ================= boss (ember king) =================

    private static void buildBoss() {
        Texture bAI = aiTex("boss");
        if (bAI != null) {
            bossTex = bAI;
            bossReg = new TextureRegion(bAI);
            return;
        }
        int w = 88, h = 76;
        Pixmap p = new Pixmap(w, h, Pixmap.Format.RGBA8888);
        drawBoss(p);
        bossTex = makeTexP(p);
        bossReg = new TextureRegion(bossTex);
        p.dispose();
    }

    private static void drawBoss(Pixmap p) {
        int cx = 44, base = 6;
        int fur = 0xffa33b20, furD = 0xff6b1f12, man = 0xffff5a26;
        // mane (flame droplets around neck)
        for (int a = 0; a < 360; a += 15) {
            float rad = (float) Math.toRadians(a);
            int mx = cx + (int) (Math.cos(rad) * 26), my = base + 40 + (int) (Math.sin(rad) * 20);
            if (my < base + 40) Art.fillTriangle(p, cx, base + 40, mx, my + 6, mx + (int) (Math.cos(rad) * 10), my, man);
            if (my < base + 42) Art.fillTriangle(p, cx, base + 40 - 2, mx, my - 4, mx - 4, my, 0xffff7a42);
        }
        // body
        drawPoly(p, cx - 30, base + 24, cx + 30, base + 24, cx + 20, base + 48, cx - 20, base + 48, HOUT);
        drawPoly(p, cx - 28, base + 26, cx + 28, base + 26, cx + 18, base + 46, cx - 18, base + 46, fur);
        // chest flame
        Art.glow(p, cx, base + 36, 12, 0x88);
        Art.fillSector(p, cx, base + 36, 9, -40, 40, 0xcc);
        Art.fillTriangle(p, cx, base + 33, cx - 5, base + 40, cx + 5, base + 40, 0xffffd054);
        // legs
        Art.fillRect(p, cx - 20, base, 12, 26, furD);
        Art.fillRect(p, cx + 8, base, 12, 26, furD);
        Art.fillRect(p, cx - 22, base - 2, 16, 5, 0xffff8a3c);
        Art.fillRect(p, cx + 6, base - 2, 16, 5, 0xffff8a3c);
        // head
        Art.fillCircle(p, cx, base + 58, 15, HOUT);
        Art.fillCircle(p, cx, base + 58, 13, fur);
        // ears/horns
        Art.fillTriangle(p, cx - 14, base + 64, cx - 24, base + 78, cx - 8, base + 70, 0xffffd054);
        Art.fillTriangle(p, cx + 14, base + 64, cx + 24, base + 78, cx + 8, base + 70, 0xffffd054);
        // eyes
        Art.fillEllipse(p, cx - 7, base + 60, 4, 2, 0xffffd054);
        Art.fillEllipse(p, cx + 7, base + 60, 4, 2, 0xffffd054);
        Art.fillRect(p, cx - 6, base + 59, 3, 1, 0xffffffff);
        Art.fillRect(p, cx + 6, base + 59, 3, 1, 0xffffffff);
        Art.fillRect(p, cx - 3, base + 54, 3, 4, 0x661a1a1a);
        Art.fillRect(p, cx + 0, base + 54, 3, 4, 0x661a1a1a);
        // snout
        Art.fillEllipse(p, cx, base + 48, 5, 3, 0x804a1a0e);
        // tail flame
        Art.fillTriangle(p, cx - 30, base + 30, cx - 46, base + 16, cx - 30, base + 20, man);
        Art.fillTriangle(p, cx - 46, base + 16, cx - 56, base + 26, cx - 40, base + 20, 0xffff7a42);
    }

    // ================= effects =================

    private static void buildEffects() {
        // slash arc (elemental crescent) - 96x96
        slashTex = makeTex(96, 96, p -> {
            for (int r = 30; r > 6; r--) {
                float t = (r - 6) / 24f;
                int col = Art.mix(0xffffffff, 0xc8a0c8ff, t);
                Art.fillSector(p, 48, 48, r, -55, 55, col);
            }
            Art.fillSector(p, 48, 48, 22, -50, 50, 0xccffffff);
        });
        slashReg = new TextureRegion(slashTex);

        // projectiles strip: 0 fire 1 ice 2 water 3 electro 4 wind 5 geo
        Pixmap p = new Pixmap(96, 40, Pixmap.Format.RGBA8888);
        drawFireball(p, 0);
        drawIceShard(p, 1);
        drawWaterLance(p, 2);
        drawElectro(p, 3);
        drawWind(p, 4);
        drawGeo(p, 5);
        projTex = makeTexP(p);
        p.dispose();
        for (int i = 0; i < 6; i++) proj[i] = new TextureRegion(projTex, i * 16, 0, 16, 40);
    }

    private static void drawFireball(Pixmap p, int f) {
        int ox = f * 16 + 8, cy = 20;
        Art.glow(p, ox, cy, 15, 0x88);
        Art.fillCircle(p, ox - 1, cy, 7, 0xffff9822);
        Art.fillCircle(p, ox, cy, 5, 0xffffcf4d);
        Art.fillCircle(p, ox, cy + 1, 2, 0xffffffff);
        Art.fillTriangle(p, ox - 4, cy + 2, ox + 4, cy + 2, ox, cy + 9, 0xffff7043);
    }

    private static void drawIceShard(Pixmap p, int f) {
        int ox = f * 16 + 8, cy = 20;
        int col = 0xff9fe8ff, colD = 0xff4db6e8;
        drawPoly(p, ox - 3, cy - 8, ox + 3, cy - 8, ox + 6, cy, ox - 6, cy, 0xff2b6ea0);
        drawPoly(p, ox - 2, cy - 8, ox + 2, cy - 8, ox + 4, cy, ox - 4, cy, col);
        drawPoly(p, ox - 6, cy, ox + 6, cy, ox + 3, cy + 8, ox - 3, cy + 8, 0xff2b6ea0);
        drawPoly(p, ox - 4, cy, ox + 4, cy, ox + 2, cy + 7, ox - 2, cy + 7, colD);
        Art.fillRect(p, ox - 1, cy - 7, 2, 14, 0xccffffff);
        Art.set(p, ox - 1, cy - 8, 0xffffffff);
    }

    private static void drawWaterLance(Pixmap p, int f) {
        int ox = f * 16 + 8, cy = 20;
        int col = 0xff5ce0ee, colD = 0xff1f9fbb;
        Art.glow(p, ox, cy, 10, 0x66);
        drawPoly(p, ox - 3, cy - 10, ox + 3, cy - 10, ox, cy - 14, ox, cy - 14, colD);
        drawPoly(p, ox - 5, cy - 10, ox + 5, cy - 10, ox + 4, cy, ox - 4, cy, colD);
        drawPoly(p, ox - 4, cy - 9, ox + 4, cy - 9, ox + 3, cy - 1, ox - 3, cy - 1, col);
        drawPoly(p, ox - 4, cy, ox + 4, cy, ox + 2, cy + 8, ox - 2, cy + 8, colD);
        drawPoly(p, ox - 3, cy + 1, ox + 3, cy + 1, ox + 2, cy + 7, ox - 2, cy + 7, col);
        Art.fillRect(p, ox - 1, cy - 8, 2, 12, 0xccffffff);
    }

    private static void drawElectro(Pixmap p, int f) {
        int ox = f * 16 + 8, cy = 20;
        Art.glow(p, ox, cy, 12, 0x99);
        Art.fillCircle(p, ox, cy, 5, 0xffffeb7a);
        for (int a = 0; a < 360; a += 45) {
            float rad = (float) Math.toRadians(a);
            int x1 = ox + (int) (Math.cos(rad) * 6), y1 = cy + (int) (Math.sin(rad) * 6);
            int x2 = ox + (int) (Math.cos(rad + 0.35f) * 10), y2 = cy + (int) (Math.sin(rad + 0.35f) * 10);
            thickLine(p, x1, y1, x2, y2, 2, 0xffffffcc);
        }
    }

    private static void drawWind(Pixmap p, int f) {
        int ox = f * 16 + 8, cy = 20;
        Art.glow(p, ox, cy, 11, 0x77);
        for (int i = 0; i < 3; i++) {
            int yy = cy - 4 + i * 4;
            Art.fillEllipse(p, ox, yy, 8 - i, 2, 0xccd6faff);
            Art.fillEllipse(p, ox + 2, yy, 5 - i, 1, 0xfff6fbff);
        }
    }

    private static void drawGeo(Pixmap p, int f) {
        int ox = f * 16 + 8, cy = 20;
        Art.glow(p, ox, cy, 10, 0x77);
        Art.fillRect(p, ox - 4, cy - 4, 8, 8, 0xffd9a322);
        Art.fillRect(p, ox - 2, cy - 2, 4, 4, 0xffffe082);
        Art.set(p, ox - 1, cy - 1, 0xffffffff);
    }

    // ================= waypoint statue =================

    private static void buildWaypoint() {
        Texture wpAI = aiTex("waypoint");
        if (wpAI != null) {
            waypointTex = wpAI;
            wpReg = new TextureRegion(wpAI);
            return;
        }
        int w = 40, h = 56;
        Pixmap p = new Pixmap(w, h, Pixmap.Format.RGBA8888);
        int base = h;
        // shadow
        Art.fillEllipse(p, 20, base - 2, 18, 4, 0x50000000);
        // pedestal
        Art.fillRect(p, 10, base - 28, 20, 6, 0xff5d4037);
        Art.fillRect(p, 7, base - 34, 26, 6, 0xff795548);
        Art.fillRect(p, 11, base - 34, 8, 6, 0xff8d6e63);
        // pillar
        Art.fillRect(p, 17, base - 46, 6, 12, 0xff6d4c41);
        Art.fillRect(p, 18, base - 48, 4, 2, 0xffa1887f);
        // floating orb
        Art.glow(p, 20, base - 14, 14, 0x88);
        Art.fillCircle(p, 20, base - 14, 7, 0xfffff7d0);
        Art.fillCircle(p, 20, base - 14, 5, 0xffffe58a);
        Art.fillCircle(p, 20, base - 14, 2, 0xffffffff);
        // ring halo
        Art.outlineEllipse(p, 20, base - 15, 11, 4, 0x66ffffff);
        waypointTex = makeTexP(p);
        wpReg = new TextureRegion(waypointTex);
        p.dispose();
    }

    // ================= element icons =================

    private static void buildIcons() {
        int w = 24, h = 24;
        Pixmap p = new Pixmap(w * Element.values().length, h, Pixmap.Format.RGBA8888);
        Element[] es = Element.values();
        for (int i = 0; i < es.length; i++) {
            int ox = i * w;
            Art.fillCircle(p, ox + 12, 12, 12, 0x80000000);
            Art.fillCircle(p, ox + 12, 12, 11, 0xee + (es[i].bright & 0xff));
            Art.glow(p, ox + 12, 12, 11, es[i].bright);
            Art.outlineCircle(p, ox + 12, 12, 11, 0xcc000000);
            // little symbol: cross/star
            int c = (es[i].bright & 0x00ffffff);
            Art.fillCircle(p, ox + 12, 12, 5, 0xffffffff & 0x00ffffff | 0xcc000000);
            Art.fillCircle(p, ox + 12, 12, 4, es[i].bright);
            Art.fillEllipse(p, ox + 12, 12, 2, 3, 0xffffffff);
        }
        iconTex = makeTexP(p);
        p.dispose();
        for (int i = 0; i < es.length; i++) elementIcons[i] = new TextureRegion(iconTex, i * w, 0, w, h);
    }

    // ================= 3D city surfaces & facades =================

    private static void buildCityTex() {
        t_road = makeTex(64, 64, p -> {
            Art.fillRect(p, 0, 0, 64, 64, 0xff3b3f46);
            for (int i = 0; i < 64; i += 2) speckle(p, i % 3, 0, 3, 64, 0x14, 0xff2b2e33, 3);
            // dashed center line
            for (int y = 0; y < 64; y += 4) {
                if ((y / 4) % 2 == 0) Art.fillRect(p, 30, y, 4, 2, 0xffd8d475);
            }
            Art.fillRect(p, 0, 0, 64, 2, 0xff55525c);
            Art.fillRect(p, 0, 62, 64, 2, 0xff55525c);
        });
        t_sidewalk = makeTex(64, 64, p -> {
            Art.fillRect(p, 0, 0, 64, 64, 0xffb9b2a6);
            speckle(p, 0, 0, 64, 64, 0x18, 0xffa09a8e, 4);
            Art.fillRect(p, 0, 0, 64, 2, 0xffcfc9bd);
            Art.fillRect(p, 0, 20, 64, 1, 0xff99917f);
            Art.fillRect(p, 0, 40, 64, 1, 0xff99917f);
        });
        t_grass3 = makeTex(64, 64, p -> {
            Art.fillRect(p, 0, 0, 64, 64, 0xff5b8c3a);
            speckle(p, 0, 0, 64, 64, 0x2a, 0xff6f9f47, 3);
            speckle(p, 0, 0, 64, 64, 0x18, 0xff41742b, 3);
        });
        t_park = makeTex(64, 64, p -> {
            Art.fillRect(p, 0, 0, 64, 64, 0xff69a63f);
            speckle(p, 0, 0, 64, 64, 0x30, 0xff7fbf52, 2);
            speckle(p, 0, 0, 64, 64, 0x22, 0xffd45d8c, 5);
            speckle(p, 0, 0, 64, 64, 0x22, 0xffffd740, 6);
        });
        t_plaza = makeTex(64, 64, p -> {
            Art.fillRect(p, 0, 0, 64, 64, 0xffcfc4ae);
            for (int i = 0; i < 64; i += 16) {
                Art.fillRect(p, i, 0, 1, 64, 0xffb3a78e);
                Art.fillRect(p, 0, i, 64, 1, 0xffb3a78e);
            }
            Art.fillRect(p, 0, 0, 64, 2, 0xffe2d9c4);
        });
        t_roof = makeTex(32, 32, p -> {
            Art.fillRect(p, 0, 0, 32, 32, 0xff6e6e74);
            speckle(p, 0, 0, 32, 32, 0x2c, 0xff56565c, 3);
            Art.fillRect(p, 0, 0, 32, 2, 0xff83838a);
        });

        // facade styles: base wall, frame, day glass, night glass, big windows?
        facade(0xff8a9bb0, 0xff5c6b80, 0xffdbe8f5, 0xffffe08a, false); // office blue
        facade(0xffc8b08a, 0xff9d8459, 0xffcfeaf2, 0xffffcf6e, false); // beige residential
        facade(0xffa05c48, 0xff7a4030, 0xfff4d8c8, 0xffffb45e, false); // brick
        facade(0xff7ba58c, 0xff4e7a61, 0xffeafff0, 0xffc9f09a, true);  // glass green
        facade(0xffcfc6b8, 0xffa89c8a, 0xffe6f2f7, 0xffffd984, false); // marble
        facade(0xff98546a, 0xff713a4d, 0xfff5dbe4, 0xffffb3c1, false); // rose
    }

    private static void facade(int base, int frame, int glassDay, int glassNight, boolean big) {
        int w = 64, h = 64;
        Pixmap d = new Pixmap(w, h, Pixmap.Format.RGBA8888);
        Pixmap n = new Pixmap(w, h, Pixmap.Format.RGBA8888);
        int rows = big ? 5 : 6;
        int cols = big ? 2 : 4;
        int m = 3;
        float cw = (w - m * 2f) / cols, ch = (h - m * 2f) / rows;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int x0 = (int) (m + col * cw), y0 = (int) (m + row * ch);
                int cw2 = (int) cw - 2, ch2 = (int) ch - 2;
                // frame
                Art.fillRect(d, x0, y0, cw2, ch2, frame);
                Art.fillRect(n, x0, y0, cw2, ch2, frame);
                // glass
                int gx = x0 + 2, gy = y0 + 2, gw = cw2 - 4, gh = ch2 - 4;
                Art.fillRect(d, gx, gy, gw, gh, glassDay);
                Art.fillRect(n, gx, gy, gw, gh, glassNight);
                // divider on big glass
                if (big) {
                    Art.fillRect(d, gx + gw / 2, gy, 2, gh, frame);
                    Art.fillRect(n, gx + gw / 2, gy, 2, gh, frame);
                }
            }
        }
        // base wall margin + subtle roofline
        Art.fillRect(d, 0, 0, w, m, 0x90000000);
        Art.fillRect(n, 0, 0, w, m, 0x90000000);
        // store two textures per style via shared slot
        facDay[stringIdx] = makeTexP(d);
        facNight[stringIdx] = makeTexP(n);
        stringIdx++;
        d.dispose();
        n.dispose();
    }

    // facade style index shared between facade() calls
    private static int stringIdx;
}

