                : "Движение: WASD/стрелки  Атака: J  Навык: K  Рывок: L  Прыжок: Пробел";
        layout.setText(Fonts.small, controls);
        Fonts.small.draw(batch, controls, cx - layout.width / 2, cy - 76);
