package com.elementia.world;

import com.badlogic.gdx.graphics.g2d.SpriteBatch;
import com.elementia.core.Art;
import com.elementia.core.Assets;

/** Simple pooled particle system with additive-ish glow dots. */
public class Particles {
    public static final int N = 320;

    public float[] x = new float[N], y = new float[N], vx = new float[N], vy = new float[N];
    public float[] life = new float[N], maxLife = new float[N], size = new float[N];
    public int[] color = new int[N];
