display.text:
apply plugin: 'com.android.application'

def keystoreProps = new Properties()
def keystoreFile = file('keystore.properties')
if (keystoreFile.exists()) keystoreProps.load(new FileInputStream(keystoreFile))

android {
    namespace 'com.elementia'
    compileSdk 34

    defaultConfig {
        applicationId 'com.elementia'
        minSdkVersion 24
        targetSdkVersion 34
        versionCode 8
        versionName '1.6.1'
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    signingConfigs {
        release {
            storeFile file('elementia-release.keystore')
            storePassword keystoreProps['storePassword']
            keyAlias keystoreProps['keyAlias']
            keyPassword keystoreProps['keyPassword']
        }
    }

    sourceSets {
        main {
            manifest.srcFile 'src/main/AndroidManifest.xml'
            java.srcDirs = ['src/main/java']
            aidl.srcDirs = ['src/main/java']
            renderscript.srcDirs = ['src/main/java']
            res.srcDirs = ['src/main/res']
            // Core resources (game art + font) are bundled straight from the
            // shared module so desktop and Android ship identical files.
            assets.srcDirs = ['src/main/assets', '../core/src/main/resources']
            jniLibs.srcDirs = ['libs']
        }
    }

    buildTypes {
        debug {
            debuggable true
        }
        release {
            minifyEnabled false
            signingConfig signingConfigs.release
        }
    }

    lintOptions {
        abortOnError false
        checkReleaseBuilds false
    }
}

configurations { natives }

dependencies {
    implementation project(':core')
    implementation "com.badlogicgames.gdx:gdx-backend-android:1.13.1"
    implementation "com.badlogicgames.gdx:gdx-freetype:1.13.1"
    natives "com.badlogicgames.gdx:gdx-platform:1.13.1:natives-armeabi-v7a"
    natives "com.badlogicgames.gdx:gdx-platform:1.13.1:natives-arm64-v8a"
    natives "com.badlogicgames.gdx:gdx-platform:1.13.1:natives-x86"
    natives "com.badlogicgames.gdx:gdx-platform:1.13.1:natives-x86_64"
    natives "com.badlogicgames.gdx:gdx-freetype-platform:1.13.1:natives-armeabi-v7a"
    natives "com.badlogicgames.gdx:gdx-freetype-platform:1.13.1:natives-arm64-v8a"
    natives "com.badlogicgames.gdx:gdx-freetype-platform:1.13.1:natives-x86"
    natives "com.badlogicgames.gdx:gdx-freetype-platform:1.13.1:natives-x86_64"
}

// Extract native .so files from gdx-platform jars into the jniLibs directories
task copyAndroidNatives {
    doFirst {
        configurations.getByName("natives").copy().files.each { jar ->
            def outputDir = null
            if (jar.name.endsWith("natives-arm64-v8a.jar")) outputDir = file("libs/arm64-v8a")
            else if (jar.name.endsWith("natives-armeabi-v7a.jar")) outputDir = file("libs/armeabi-v7a")
            else if (jar.name.endsWith("natives-x86.jar")) outputDir = file("libs/x86")
            else if (jar.name.endsWith("natives-x86_64.jar")) outputDir = file("libs/x86_64")
            if (outputDir != null) {
                outputDir.mkdirs()
                copy {
                    from zipTree(jar)
                    into outputDir
                    include "*.so"
                }
            }
        }
    }
}

tasks.matching { it.name.contains("merge") && it.name.contains("JniLibFolders") }.configureEach {
    dependsOn 'copyAndroidNatives'
}

